import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, Group, Mesh, BoxGeometry } from 'three/webgpu';
import { uv, mix, color, add, mul } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry } = ctx.THREE;
  const root = new Group();

  // ---------- CONFIG ----------
  const gridW = 5.5;
  const gridH = 3.5;
  const gutter = 0.25;
  const depth = 0.06;
  const padding = 0.5;
  const tickSize = { w: 0.4, h: 0.05 };
  const tickEmissive = 1.3;

  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStart: '#101017',
    gradientEnd: '#1a1a22',
  };

  // ---------- TEXT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Helper to create text
  function makeText(content, opts) {
    const txt = ctx.fontAtlas.createText(content, opts);
    return txt;
  }

  // ---------- GRID ----------
  const cells = [];

  // Dominant cell (left column)
  const domW = 3.25;
  const domH = 3.5;
  const domX = -gridW / 2 + domW / 2 + gutter / 2;
  const domY = 0;
  cells.push({ w: domW, h: domH, x: domX, y: domY, type: 'dominant' });

  // Secondary cells (right column)
  const secW = 2.0;
  const secH = 1.625;
  const secX = gridW / 2 - secW / 2 - gutter / 2;
  const secYTop = gridH / 2 - secH / 2 - gutter / 2;
  const secYBottom = -gridH / 2 + secH / 2 + gutter / 2;
  cells.push({ w: secW, h: secH, x: secX, y: secYTop, type: 'secondary' });
  cells.push({ w: secW, h: secH, x: secX, y: secYBottom, type: 'secondary' });

  // ---------- MATERIAL ----------
  function createCellMaterial() {
    const mat = new MeshStandardNodeMaterial({
      metalness: 0.45,
      roughness: 0.5,
      clearcoat: 0.2,
      transparent: true,
      depthWrite: true,
      side: ctx.THREE.DoubleSide,
    });

    // Diagonal gradient (135°)
    const uvNode = uv();
    const t = add(
      mul(uvNode.x, 0.70710678),
      mul(uvNode.y, 0.70710678)
    );
    const grad = mix(color(colors.gradientStart), color(colors.gradientEnd), t);
    mat.colorNode = grad;
    mat.emissiveNode = color('#000000');
    return mat;
  }

  // ---------- BUILD CELLS ----------
  const cellMeshes = [];
  cells.forEach((cell, i) => {
    const geom = new BoxGeometry(cell.w, cell.h, depth);
    const mat = createCellMaterial();
    const mesh = new Mesh(geom, mat);
    mesh.position.set(cell.x, cell.y, depth / 2);
    mesh.material.opacity = 0;
    mesh.position.y += 0.2; // initial offset for animation
    root.add(mesh);
    cellMeshes.push(mesh);

    // Tick bar
    const tickGeom = new BoxGeometry(tickSize.w, tickSize.h, depth);
    const tickMat = new MeshStandardNodeMaterial({
      emissive: color(colors.accent),
      emissiveIntensity: tickEmissive,
      metalness: 0,
      roughness: 1,
      transparent: true,
    });
    const tick = new Mesh(tickGeom, tickMat);
    const tickX = -cell.w / 2 + padding + tickSize.w / 2;
    const tickY = cell.h / 2 - padding - tickSize.h / 2;
    tick.position.set(tickX, tickY, depth / 2 + 0.001);
    mesh.add(tick);
  });

  // ---------- TEXT ----------
  let txtIdx = 0;
  // Header caption above grid
  if (items[txtIdx]) {
    const captionItem = items[txtIdx++];
    const caption = makeText(captionItem.text, {
      fontSize: 18,
      color: colors.paper,
      align: 'left',
    });
    caption.position.set(-gridW / 2, gridH / 2 + 0.5, 0);
    root.add(caption);
  }

  // Dominant cell texts
  if (items[txtIdx]) {
    const valLarge = items[txtIdx++];
    const txt = makeText(valLarge.text, {
      fontSize: 124,
      color: colors.ink,
      align: 'center',
    });
    txt.position.set(cells[0].x, cells[0].y + 0.2, depth / 2 + 0.01);
    root.add(txt);
  }
  if (items[txtIdx]) {
    const label = items[txtIdx++];
    const txt = makeText(label.text, {
      fontSize: 18,
      color: colors.paper,
      align: 'center',
    });
    txt.position.set(cells[0].x, cells[0].y - 0.2, depth / 2 + 0.01);
    root.add(txt);
  }

  // Secondary cells
  for (let c = 1; c < cells.length; c++) {
    if (items[txtIdx]) {
      const val = items[txtIdx++];
      const txt = makeText(val.text, {
        fontSize: 68,
        color: colors.ink,
        align: 'center',
      });
      txt.position.set(cells[c].x, cells[c].y + 0.1, depth / 2 + 0.01);
      root.add(txt);
    }
    if (items[txtIdx]) {
      const label = items[txtIdx++];
      const txt = makeText(label.text, {
        fontSize: 18,
        color: colors.paper,
        align: 'center',
      });
      txt.position.set(cells[c].x, cells[c].y - 0.1, depth / 2 + 0.01);
      root.add(txt);
    }
  }

  // ---------- ANIMATION ----------
  const timelines = [];

  // Staggered fade‑up for cells
  const tl = gsap.timeline();
  cellMeshes.forEach((mesh, i) => {
    tl.to(
      mesh.position,
      { y: mesh.position.y - 0.2, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      i * 0.08
    );
    tl.to(
      mesh.material,
      { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      i * 0.08
    );
  });
  timelines.push(tl);

  // Hover handlers
  root.userData.handlers = {
    pointerover: () => {
      const hoverTl = gsap.timeline();
      hoverTl.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      timelines.push(hoverTl);
    },
    pointerout: () => {
      const outTl = gsap.timeline();
      outTl.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        onComplete: () => {
          // weighted‑settle overshoot
          gsap.to(root.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.2,
            ease: 'power4.out',
          });
        },
      });
      timelines.push(outTl);
    },
  };

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    cellMeshes.forEach(m => {
      m.geometry.dispose();
      if (m.material.dispose) m.material.dispose();
    });
    root.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material && obj.material.dispose) obj.material.dispose();
    });
  };

  return root;
}
